-- Checksum (chi doc) cac dong co tu truoc 21/10 o 4 bang gia — tru 8 dong pcc he so cu SG hang ETEK Green (duoc phep doi trang thai). Chay TRUOC va SAU lenh chep gia: phai GIONG HET.
SELECT 'product_company_units' bang, COUNT(*) so_dong, SUM(CRC32(CONCAT_WS('|',IFNULL(`id`,'~'),IFNULL(`product_unit_id`,'~'),IFNULL(`company_id`,'~'),IFNULL(`product_id`,'~'),IFNULL(`cost_price`,'~'),IFNULL(`buy_price`,'~'),IFNULL(`sale_max_percent_coefficient`,'~'),IFNULL(`liquidation_sale_max_percent`,'~'),IFNULL(`according_base_price`,'~'),IFNULL(`price_wait_approve`,'~'),IFNULL(`coefficient_wait_approve`,'~'),IFNULL(`sale_max_percent_wait_approve`,'~'),IFNULL(`flag_price_wait_approve`,'~'),IFNULL(`approve_comment`,'~'),IFNULL(`approve_time`,'~'),IFNULL(`reason_edit_price`,'~'),IFNULL(`note_edit_price`,'~'),IFNULL(`created_by`,'~'),IFNULL(`updated_by`,'~'),IFNULL(`created_at`,'~'),IFNULL(`updated_at`,'~')))) tong_crc, BIT_XOR(CRC32(MD5(CONCAT_WS('|',IFNULL(`id`,'~'),IFNULL(`product_unit_id`,'~'),IFNULL(`company_id`,'~'),IFNULL(`product_id`,'~'),IFNULL(`cost_price`,'~'),IFNULL(`buy_price`,'~'),IFNULL(`sale_max_percent_coefficient`,'~'),IFNULL(`liquidation_sale_max_percent`,'~'),IFNULL(`according_base_price`,'~'),IFNULL(`price_wait_approve`,'~'),IFNULL(`coefficient_wait_approve`,'~'),IFNULL(`sale_max_percent_wait_approve`,'~'),IFNULL(`flag_price_wait_approve`,'~'),IFNULL(`approve_comment`,'~'),IFNULL(`approve_time`,'~'),IFNULL(`reason_edit_price`,'~'),IFNULL(`note_edit_price`,'~'),IFNULL(`created_by`,'~'),IFNULL(`updated_by`,'~'),IFNULL(`created_at`,'~'),IFNULL(`updated_at`,'~'))))) xor_md5 FROM product_company_units WHERE (created_at IS NULL OR created_at<'2026-10-21');
