SELECT 'product_company_coefficients' bang, COUNT(*) so_dong, SUM(CRC32(CONCAT_WS('|',IFNULL(`id`,'~'),IFNULL(`product_id`,'~'),IFNULL(`company_id`,'~'),IFNULL(`coefficient`,'~'),IFNULL(`status`,'~'),IFNULL(`business_policy_id`,'~'),IFNULL(`min_stock_qty`,'~'),IFNULL(`guarantee`,'~'),IFNULL(`guarantee_type`,'~'),IFNULL(`created_by`,'~'),IFNULL(`updated_by`,'~'),IFNULL(`info_entered_at`,'~'),IFNULL(`created_at`,'~'),IFNULL(`updated_at`,'~')))) tong_crc, BIT_XOR(CRC32(MD5(CONCAT_WS('|',IFNULL(`id`,'~'),IFNULL(`product_id`,'~'),IFNULL(`company_id`,'~'),IFNULL(`coefficient`,'~'),IFNULL(`status`,'~'),IFNULL(`business_policy_id`,'~'),IFNULL(`min_stock_qty`,'~'),IFNULL(`guarantee`,'~'),IFNULL(`guarantee_type`,'~'),IFNULL(`created_by`,'~'),IFNULL(`updated_by`,'~'),IFNULL(`info_entered_at`,'~'),IFNULL(`created_at`,'~'),IFNULL(`updated_at`,'~'))))) xor_md5 FROM product_company_coefficients WHERE (created_at IS NULL OR created_at<'2026-10-21') AND id NOT IN (2292,1711,2285,2271,2272,2274,2280,2282);
